pg={r['IncidentRef']:r for r in rows('db-crn-paging-archive')}
print('--roster vs paging')
for ref,r in R.items():
    p=pg[ref]
    if T(r['actual_dispatch'])!=T(p['DispatchUtc']): print(ref,'disp',r['actual_dispatch'],p['DispatchDepotLocal'])
    if T(r['actual_handback'])!=T(p['AutoLoggedClearUtc']): print(ref,'hb',r['actual_handback'],p['AutoLoggedClearDepotLocal'],C[ref]['hbsrc'])
print('--actuals feed vs paging')
for a in rows('db-crn-roster-actuals-feed'):
    ref=a['IncidentRef']; p=pg[ref]; c=C[ref]
    if a['EngineerId']!=R[ref]['engineer_id']: print(ref,'eng',a['EngineerId'],R[ref]['engineer_id'])
    if T(a['KeyedDispatchLocal'])!=T(p['DispatchUtc']): print(ref,'kdisp',a['KeyedDispatchLocal'],p['DispatchDepotLocal'])
    if T(a['KeyedClearLocal'])!=T(p['AutoLoggedClearUtc']): print(ref,'kclr',a['KeyedClearLocal'],p['AutoLoggedClearDepotLocal'])
    if a['KeyedTravelMinutes']!=c['travel']: print(ref,'ktravel',a['KeyedTravelMinutes'],c['travel'])
print('--rollups vs legs')
legs=rows('db-crn-van-leg-records')
for t in rows('db-crn-van-telemetry-summaries'):
    L=[l for l in legs if l['VanCode']==t['VanCode'] and l['WeekCommencing']==t['WeekCommencing']]
