print('--leg van vs roster van')
for l in legs:
    if l['VanCode']!=R[l['IncidentRef']]['van']: print(l['IncidentRef'],l['VanCode'],R[l['IncidentRef']]['van'])
print('--badge (archive clock) vs paging')
for b in csv.DictReader(open('/workspace/data/badge-access-export-2026-11-01.csv')):
    ref=b['incident_ref']
    if ref not in R: print('badge unknown',ref); continue
    bo=datetime.fromisoformat(b['badge_out']).replace(tzinfo=timezone.utc)
    if b['engineer_id']!=R[ref]['engineer_id']: print(ref,'badge eng',b['engineer_id'],R[ref]['engineer_id'])
    hb=T(C[ref]['hb'])
    if bo!=hb: print(ref,'badge_out',bo,'hb',hb,C[ref]['hbsrc'],'clear',pg[ref]['AutoLoggedClearUtc'])
