import json,glob,sys,os
# collect all tool_result payloads from session jsonl files (main + subagents)
files=sorted(glob.glob('/logs/agent/sessions/projects/-workspace/**/*.jsonl',recursive=True))
results=[]
for f in files:
    for line in open(f):
        try: d=json.loads(line)
        except: continue
        msg=d.get('message',{})
        if not isinstance(msg,dict): continue
        c=msg.get('content')
        if not isinstance(c,list): continue
        for part in c:
            if isinstance(part,dict) and part.get('type')=='tool_result':
                cc=part.get('content')
                texts=[]
                if isinstance(cc,str): texts=[cc]
                elif isinstance(cc,list): texts=[x.get('text','') for x in cc if isinstance(x,dict)]
                for t in texts:
                    try: results.append((d.get('timestamp',''),json.loads(t)))
                    except: pass
pages={}
def walk(o,ts):
    if isinstance(o,dict):
        if 'id' in o and 'properties' in o and 'parent_id' in o:
            pages[o['id']]=(ts,o)
        for v in o.values(): walk(v,ts)
    elif isinstance(o,list):
        for v in o: walk(v,ts)
for ts,r in sorted(results,key=lambda x:x[0]):
    walk(r,ts)
json.dump({k:v[1] for k,v in pages.items()},open('/tmp/out/pages.json','w'),indent=1)
from collections import Counter
print(len(pages)); print(Counter(v[1]['parent_id'] for v in pages.values()))
