import json
from datetime import datetime,timezone,timedelta
P=json.load(open('/tmp/out/pages.json')); R=json.load(open('/tmp/out/roster.json'))
def rows(db): return [{k:v.get('value') for k,v in p['properties'].items()}|{'_id':p['id'],'_edited':p.get('last_edited_time')} for p in P.values() if p['parent_id']==db]
T=lambda s: datetime.fromisoformat(s.replace('Z','+00:00'))
pg={r['IncidentRef']:r for r in rows('db-crn-paging-archive')}
legs={}
for r in rows('db-crn-van-leg-records'): legs.setdefault(r['IncidentRef'],[]).append(r)
pw={r['IncidentRef']:r for r in rows('db-crn-parts-wait-log')}
ra={r['IncidentRef']:r for r in rows('db-crn-remote-attempt-log')}
hbc={r['IncidentRef']:r for r in rows('db-crn-handback-certificates')}
REVC=datetime(2026,10,19,0,0,tzinfo=timezone(timedelta(hours=1)))
out=[]
for ref,p in sorted(pg.items(),key=lambda x:x[1]['DispatchUtc']):
    d=T(p['DispatchUtc']); a=T(p['AcknowledgedUtc']); c=T(p['AutoLoggedClearUtc'])
    # consistency checks
    for u,l in [('DispatchUtc','DispatchDepotLocal'),('AcknowledgedUtc','AcknowledgedDepotLocal'),('AutoLoggedClearUtc','AutoLoggedClearDepotLocal')]:
        if T(p[u])!=T(p[l]): print('UTC/local mismatch',ref,u,p[u],p[l])
    rev='C' if T(p['DispatchDepotLocal'])>=REVC else 'B'
    ro=R.get(ref); eng=ro['engineer_id'] if ro else None
    lg=legs.get(ref,[]); travel=sum(x['TravelMinutes'] for x in lg)
    hb=c; hbsrc='clear'
    if ref in hbc and hbc[ref]['SignatureStatus']=='countersigned':
        hb=T(hbc[ref]['DeclaredHandbackDepotLocal']); hbsrc='HBC'
    ack=int((a-d).total_seconds()//60)
    w=pw[ref]['LoggedWaitMinutes'] if ref in pw else 0
    rem=ra[ref]['FirstAttemptMinutesAfterDispatch'] if ref in ra else None
    if rev=='B':
        allow=165; actual=int((hb-d).total_seconds()//60)
    else:
        allow=120+min(travel,60)
        if rem is not None and rem<=15: actual=rem
        else: actual=int((hb-a).total_seconds()//60)-w
    out.append(dict(ref=ref,eng=eng,rev=rev,disp_local=p['DispatchDepotLocal'],ack=ack,travel=travel,nlegs=len(lg),wait=w,rem=rem,hbsrc=hbsrc,clear_min=int((c-d).total_seconds()//60),allow=allow,actual=actual,excess=actual-allow,pg=p['PagingRecordRef'],van=ro['van'] if ro else None,rd=ro['actual_dispatch'] if ro else None,rh=ro['actual_handback'] if ro else None, hb=hb.isoformat()))
json.dump(out,open('/tmp/out/calls.json','w'),indent=1)
for o in out:
    flag=('RESP' if o['excess']>0 else '')+(' ACK' if o['ack']>20 else '')
    print(o['ref'],o['eng'],o['rev'],o['disp_local'][5:16],'ack',o['ack'],'tr',o['travel'],o['nlegs'],'w',o['wait'],'rem',o['rem'],o['hbsrc'],'allow',o['allow'],'act',o['actual'],'exc',o['excess'],flag)
EOF
